if (row.stage !== 'in_progress' || !row.assignee) return true;
if (ctx.old && ctx.old.stage === 'in_progress' && ctx.old.assignee === row.assignee) return true;
const id = (ctx.old && ctx.old.id) || row.id || null;
const r = await ctx.db.query("select count(*)::int as n from card where assignee = $1 and stage = 'in_progress' and ($2::uuid is null or id <> $2::uuid)", [row.assignee, id]);
const rows = Array.isArray(r) ? r : (r && r.rows) ? r.rows : [];
const n = rows.length ? Number(rows[0].n) : 0;
return n >= 3 ? 'WIP limit reached: this teammate already has 3 cards in progress.' : true;

