      { label: "Cards done", v: total ? Math.round((done / total) * 100) : 0, Icon: Trophy, suffix: "%", alert: false },
      { label: "Overdue", v: overdue, Icon: Flame, suffix: "", alert: overdue > 0 },
    ];
    const advance = async (p: R) => {
      const to = nextSt[s(p.status)]; if (!to) return;
      try { await app.transition("project", s(p.id), "status", to); say(s(p.name) + " is now " + stLabel[to]); } catch (e) { say(msg(e), true); }
    };
    const loadingP = app.loading("project") && projects.length === 0;
    const order: Record<string, number> = { active: 0, planning: 1, shipped: 2 };
