          <p className={sub}>{projects.length} projects · active first, then by due date</p>
          <div className="mt-5 grid grid-cols-2 overflow-hidden rounded-xl border border-border bg-card lg:grid-cols-4">
            {kpis.map((k, i) => (
              <div key={k.label} className={"p-4 lg:p-5 " + (i % 2 ? "border-l border-border " : "") + (i > 1 ? "border-t border-border lg:border-t-0 " : "") + (i === 2 ? "lg:border-l" : "")}>
                <div className="flex items-center gap-1.5 text-[12px] text-muted-foreground"><k.Icon className="h-3.5 w-3.5" />{k.label}</div>
                <div className={"mt-2 text-[28px] font-semibold leading-none tracking-tight tabular-nums " + (k.alert ? "text-[#FF8F8F]" : "")}><Count v={k.v} suffix={k.suffix} /></div>
              </div>
            ))}
          </div>
          {loadingP ? <div className="mt-6"><Skeleton rows={3} h={120} /></div> : projects.length === 0 ? (
            <div className="mt-6 rounded-xl border border-dashed border-border px-6 py-12 text-center"><Layers className="mx-auto h-6 w-6 text-muted-foreground" /><div className="mt-3 text-[15px] font-medium">No projects yet</div><p className="mx-auto mt-1 max-w-xs text-[13px] text-muted-foreground">Projects group cards on the board. Once one exists you'll see its progress here.</p></div>
          ) : (
          <div className="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-3">
            {sortedP.map((p, i) => {
              const pc = cardsRaw.filter((c) => s(c.project) === s(p.id));
              const pd = pc.filter((c) => s(c.stage) === "done").length;
              const pct = pc.length ? Math.round((pd / pc.length) * 100) : 0;
              const people = Array.from(new Set(pc.map((c) => s(c.assignee)).filter(Boolean))).slice(0, 4);
