                    <div className="mt-2 flex h-1.5 gap-0.5 overflow-hidden rounded-full" title={STAGES.map((sg) => ST_LABEL[sg] + " " + pc.filter((x) => s(x.stage) === sg).length).join(" · ")}>
                      {pc.length === 0 ? <div className="flex-1 bg-muted" /> : STAGES.map((sg) => { const c = pc.filter((x) => s(x.stage) === sg).length; return c ? <div key={sg} style={{ flex: c, background: ST_COLOR[sg] }} /> : null; })}
