  let rowIdx = 0;
  return (
    <Shell app={app} view="work" title="My work">
      <div className="mx-auto max-w-[860px] px-4 pb-10 pt-6 lg:px-8 lg:pt-8">
        <h2 className={h2}>{greeting}, {first}</h2>
        <p className={sub}>{dateLine ? dateLine + " · " : ""}{isMgr ? "Everything open across the team, soonest due first." : mine.length ? `${mine.length} open card${mine.length === 1 ? "" : "s"}, ${inProg} of 3 in progress.` : "Nothing assigned to you right now."}</p>
        <div className="mt-5 grid grid-cols-2 overflow-hidden rounded-xl border border-border bg-card sm:grid-cols-4">
