            <div className="divide-y divide-border overflow-hidden rounded-xl border border-border bg-card">
              {g.rows.map((c) => {
                const id = s(c.id); const its = (itemsBy[id] || []).slice().sort((a, b) => n(a.position) - n(b.position)); const dn = its.filter((i) => !!i.done).length; const isOpen = open === id; const idx = rowIdx++;
                const who = s(mById[s(c.assignee)]?.name);
                return (
                  <motion.div key={id} {...enter(idx)}>
                    <button onClick={() => setOpen(isOpen ? "" : id)} aria-expanded={isOpen} className="flex min-h-[60px] w-full items-center gap-3 px-4 py-3 text-left hover:bg-muted/40">
