                      <div className="min-w-0 flex-1">
                        <div className="truncate text-[14px] font-medium">{s(c.title)}</div>
                        <div className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-[12px] text-muted-foreground">
                          <span className="font-mono text-[11px]">{s(pById[s(c.project)]?.code)}</span>
                          {s(c.due) && <span className={"flex items-center gap-1 " + (late(c) ? "text-[#FF8F8F]" : "")}><CalendarDays className="h-3.5 w-3.5" />{fmtDate(s(c.due))}</span>}
                          {its.length > 0 && <span className="flex items-center gap-1 tabular-nums"><Check className="h-3.5 w-3.5" />{dn}/{its.length}</span>}
                          {isMgr && who && <span className="flex items-center gap-1.5"><Av name={who} size={16} />{who.split(" ")[0]}</span>}
                        </div>
                      </div>
                      <PriIcon p={s(c.priority)} size={14} />
                      <motion.span animate={{ rotate: isOpen ? 180 : 0 }} transition={TW} className="text-muted-foreground"><ChevronDown className="h-4 w-4" /></motion.span>
                    </button>
                    <AnimatePresence initial={false}>
                      {isOpen && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={reduce ? { duration: 0 } : TW} className="overflow-hidden">
                          <div className="border-t border-border/60 bg-background/40 px-4 pb-4 pt-3">
                            {s(c.description) && <p className="text-[13px] leading-relaxed text-muted-foreground">{s(c.description)}</p>}
                            <div className="mt-3 flex flex-wrap gap-1.5" role="group" aria-label="Stage">
                              {STAGES.map((sg) => (<button key={sg} onClick={() => void move(c, sg)} aria-pressed={s(c.stage) === sg} className={"flex h-9 items-center gap-1.5 rounded-lg border px-2.5 text-[12px] font-medium transition-colors " + (s(c.stage) === sg ? "border-primary/60 bg-primary/15 text-foreground" : "border-border text-muted-foreground hover:text-foreground")}><StageIcon st={sg} size={12} />{ST_LABEL[sg]}</button>))}
                            </div>
                            {its.length > 0 && (
                              <div className="mt-3 flex flex-col">
                                {its.map((it) => (
                                  <button key={s(it.id)} onClick={() => void toggleItem(it)} role="checkbox" aria-checked={!!it.done} className="flex min-h-[40px] items-center gap-2.5 rounded-lg px-1 text-left hover:bg-muted/50">
                                    <span className={"grid h-[18px] w-[18px] shrink-0 place-items-center rounded-md border transition-colors " + (it.done ? "border-primary bg-primary text-primary-foreground" : "border-border")}>{it.done ? <Check className="h-3 w-3" /> : null}</span>
                                    <span className={"text-[13px] " + (it.done ? "text-muted-foreground line-through" : "")}>{s(it.text)}</span>
                                  </button>
                                ))}
                              </div>
                            )}
                            <button onClick={() => app.navigate("/board")} className="mt-3 flex h-9 items-center gap-1 text-[13px] font-medium text-foreground underline decoration-primary underline-offset-4 hover:decoration-2">Open on the board<ChevronRight className="h-3.5 w-3.5" /></button>
                          </div>
                        </motion.div>
                      )}
                    </AnimatePresence>
                  </motion.div>
                );
              })}
            </div>
          </section>
        ))}
      </div>
      {toastEl}
    </Shell>
  );
}

